  h2{margin-bottom:10px;color:#333}
  .gc{display:grid;grid-template-columns:40px repeat(10,90px)}
  .gc>div{border:1px solid #ccc;height:40px;line-height:40px}
  .ch{background:#e8e8e8;font-weight:bold;text-align:center;user-select:none}
  .rh{background:#e8e8e8;font-weight:bold;text-align:center;user-select:none}
  .co{background:#d8d8d8}
  input.cell{width:100%;height:100%;border:none;outline:none;font:14px/1.5 Consolas,monospace;text-align:right;padding:0 6px}
  input.cell:focus{background:#fff9c4}
  input.cell.err{background:#ffcdd2}
  .ctrl{margin-top:15px}
  button{padding:8px 16px;font-size:14px;cursor:pointer;background:#4caf50;color:#fff;border:none;border-radius:4px}
  button:hover{background:#45a049}
  textarea{width:100%;max-width:940px;height:200px;margin-top:10px;font:13px Consolas,monospace;padding:8px;resize:vertical}
</style>
</head>
